   where not exists (select 1 from storage.objects o where o.bucket_id = 'strike-media' and o.name = wanted.name);
  if v_missing > 0 then
    raise exception '% of 25 media files are not in the strike-media bucket yet; upload them first (see the header of this script)', v_missing;
  end if;

  -- The dashboard takes content types from the browser; the player needs the
  -- ones the importer would have set (captions as text/vtt, in particular).
  update storage.objects o
     set metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object('mimetype', wanted.mimetype)
    from (values
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-01-why.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s1-why.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s1-why.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-02-energy.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s2-energy.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s2-energy.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-03-roles.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s3-roles.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s3-roles.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-04-prepare.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s4-prepare.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s4-prepare.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-05-lock.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s5-isolate.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s5-isolate.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/hotspot-isolation.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-06-verify.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s6-verify.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s6-verify.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-07-group.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s7-group.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s7-group.vtt', 'text/vtt'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/scene-08-restart.jpg', 'image/jpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s8-restart.mp3', 'audio/mpeg'),
      ('ddddbce8-c7ab-4855-8bcd-821d080617ee/loto-101/v1/s8-restart.vtt', 'text/vtt')
    ) as wanted(name, mimetype)
   where o.bucket_id = 'strike-media' and o.name = wanted.name
     and coalesce(o.metadata ->> 'mimetype', '') <> wanted.mimetype;

  -- approve_media: stamp the reviewer on every image and narration.
  for v_block in select value from jsonb_array_elements(v_content -> 'blocks') loop
    if jsonb_typeof(v_block -> 'image') = 'object' and (v_block -> 'image') ? 'path' then
      v_block := jsonb_set(v_block, '{image}', (v_block -> 'image') || v_stamp);
    end if;
    if jsonb_typeof(v_block -> 'narration') = 'object' and (v_block -> 'narration') ? 'audio_path' then
      v_block := jsonb_set(v_block, '{narration}', (v_block -> 'narration') || v_stamp);
    end if;
    v_blocks := v_blocks || jsonb_build_array(v_block);
  end loop;
  v_content := jsonb_set(v_content, '{blocks}', v_blocks);

  -- import_seed_module: module, version, quiz.
  insert into public.strike_modules
    (id, tenant_id, library_scope, slug, title, description, category, tags, estimated_minutes, status)
  values (v_module, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', v_slug, 'LOTO 101: Control of Hazardous Energy', 'A 5-minute microlearning on OSHA 29 CFR 1910.147: the energy types, who does what, the seven steps of lockout/tagout, group lockout, and safe restart. Ends with a 10-question knowledge check.', 'Lockout/Tagout', array['loto', '1910.147', 'hazardous energy', 'general industry']::text[], 5, 'in_review');

  insert into public.strike_module_versions
    (id, module_id, tenant_id, library_scope, version_number, status, content, passing_score, retake_limit, validity_days, locale)
  values (v_version, v_module, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 1, 'draft', v_content, 80, null, 365, 'en');

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', 'What is the main purpose of lockout/tagout?', 'LOTO prevents the unexpected start-up or release of stored energy while people service equipment.', 0, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'To prevent unexpected start-up or release of energy while equipment is serviced', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'To keep production running during maintenance', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'To record who last used a machine', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'To stop unauthorized people from operating machines during breaks', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', 'Who is allowed to apply a lockout device?', 'Only trained, authorized employees apply locks. Affected employees recognize lockouts but don''t apply them.', 1, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'A trained authorized employee', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Any affected employee who operates the machine', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Whoever is closest to the disconnect', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Only the plant manager', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'true_false', 'Pressing the machine''s emergency stop button is enough to isolate its energy.', 'Stop buttons and control circuits are not energy-isolating devices. Isolate at the disconnect, valve, or block.', 2, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'True', false, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'False', true, 1);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'select_all', 'Select every energy source you must control on a machine that has a motor, an air cylinder, and a raised platen.', 'The motor is electrical, the air cylinder is pneumatic, and a raised platen stores gravitational energy.', 3, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Electrical', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Pneumatic', true, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Gravity', true, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Steam (there is no steam line on this machine)', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', 'What comes immediately after you apply your lock and tag?', 'After locking and tagging, release or restrain stored energy, then verify.', 4, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Release or block stored energy', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Start the repair', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Notify affected employees', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Remove the guard', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', 'How do you verify a machine is at zero energy?', 'With everyone clear, attempt a start (a qualified person does any voltage test the procedure requires), then return controls to off.', 5, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Clear everyone, try to start it, then return controls to off', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Look at the lock to confirm it is closed', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Ask the operator if it is off', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Wait five minutes', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', 'Your coworker''s lock is already on the disconnect. Are you protected?', 'Each worker must apply their own lock. Someone else''s lock protects them, not you.', 6, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'No. I must apply my own lock and tag', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Yes. One lock is enough for the crew', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Yes, if I can see them', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Only if the job takes less than 10 minutes', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'multiple_choice', 'During a shift change on a locked-out machine, what is the correct order?', 'Protection must be continuous: incoming workers apply their locks before outgoing workers remove theirs, following your plant''s shift-change procedure.', 7, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'The incoming worker locks on before the outgoing worker removes their lock', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'The outgoing worker removes their lock, then the incoming worker locks on', false, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'The supervisor removes all locks and re-applies one', false, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'The machine is restarted and locked out again', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'select_all', 'Select every action required before restarting after the work is done.', 'Clear tools, reinstall guards, confirm everyone is clear, notify affected employees, and each person removes only their own lock.', 8, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Remove tools and reinstall guards', true, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Confirm everyone is clear and notify affected employees', true, 1),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Each person removes only their own lock', true, 2),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'Remove any lock left by a coworker who went home', false, 3);

  v_question := gen_random_uuid();
  insert into public.strike_quiz_questions
    (id, module_version_id, tenant_id, library_scope, question_type, prompt, explanation, sort_order, points, required, graded)
  values (v_question, v_version, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'true_false', 'A tag may replace a lock whenever a lock is inconvenient.', 'A tag alone is used only where the written procedure says a device can''t accept a lock, and then with additional protective measures.', 9, 1, true, true);
  insert into public.strike_quiz_answers (question_id, tenant_id, library_scope, answer_text, is_correct, sort_order) values
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'True', false, 0),
    (v_question, 'ddddbce8-c7ab-4855-8bcd-821d080617ee', 'tenant', 'False', true, 1);

  -- strike-demo-wls.sh step 4: publish. Questions were inserted first because
  -- a published version's quiz is frozen by trigger.
  update public.strike_module_versions set status = 'published', published_at = now() where id = v_version;
  update public.strike_modules set status = 'published', published_at = now() where id = v_module;
  insert into public.strike_tenant_settings (tenant_id) values (v_tenant) on conflict (tenant_id) do nothing;

  -- strike-demo-wls.sh step 5: require this module before hot_work permits.
  insert into public.strike_training_requirements
    (tenant_id, module_id, source_type, required_before_start, expires_after_days, active, notes)
  select v_tenant, v_module, 'hot_work', true, null, true, 'STRIKE demo: LOTO 101: Control of Hazardous Energy before hot work'
   where not exists (
     select 1 from public.strike_training_requirements r
      where r.tenant_id = v_tenant and r.module_id = v_module and r.source_type = 'hot_work');

  raise notice 'Installed % for tenant %: module %, version % (% questions)', v_slug, v_tenant, v_module, v_version, 10;
end
$install$;

commit;
